// Generates the app's favicon set from a single source logo.
//
//   node scripts/generate-favicon.mjs
//
// Outputs (all derived from public/images/logo.png):
//   app/favicon.ico   — multi-resolution .ico (16/32/48) for browser tabs.
//   app/icon.png      — 512px PNG; Next emits <link rel="icon"> automatically.
//   app/apple-icon.png — 180px PNG for the iOS home-screen icon.
//
// `favicon.ico` cannot be code-generated by Next's `icon.tsx` convention, and
// sharp cannot encode the .ico container, so we resize with sharp and wrap the
// PNG frames in a hand-built ICONDIR. PNG-payload .ico is supported everywhere
// that matters (Vista+ / all current browsers).

import sharp from "sharp";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = resolve(root, "public/images/logo.png");

const ICO_SIZES = [16, 32, 48];

/** Wrap pre-encoded PNG frames in an ICO (ICONDIR) container. */
function buildIco(frames) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // type: 1 = icon
  header.writeUInt16LE(frames.length, 4); // image count

  const directory = Buffer.alloc(frames.length * 16);
  let offset = header.length + directory.length;

  frames.forEach((frame, i) => {
    const entry = i * 16;
    directory.writeUInt8(frame.size >= 256 ? 0 : frame.size, entry + 0); // width (0 = 256)
    directory.writeUInt8(frame.size >= 256 ? 0 : frame.size, entry + 1); // height
    directory.writeUInt8(0, entry + 2); // palette size
    directory.writeUInt8(0, entry + 3); // reserved
    directory.writeUInt16LE(1, entry + 4); // color planes
    directory.writeUInt16LE(32, entry + 6); // bits per pixel
    directory.writeUInt32LE(frame.data.length, entry + 8); // bytes of PNG data
    directory.writeUInt32LE(offset, entry + 12); // offset to PNG data
    offset += frame.data.length;
  });

  return Buffer.concat([header, directory, ...frames.map((f) => f.data)]);
}

// iOS "squircle"-style corner radius as a fraction of the icon's side.
const CORNER_RATIO = 0.22;

async function resizePng(size, { rounded = true } = {}) {
  let img = sharp(SOURCE)
    .resize(size, size, { fit: "cover" })
    .ensureAlpha(); // Next's ICO decoder requires RGBA PNG frames.

  if (rounded) {
    const r = Math.round(size * CORNER_RATIO);
    const mask = Buffer.from(
      `<svg width="${size}" height="${size}"><rect width="${size}" height="${size}" rx="${r}" ry="${r}" fill="#fff"/></svg>`,
    );
    // dest-in keeps the logo only where the rounded-rect mask is opaque,
    // making the corners transparent.
    img = img.composite([{ input: mask, blend: "dest-in" }]);
  }

  return img.png().toBuffer();
}

async function main() {
  const icoFrames = await Promise.all(
    ICO_SIZES.map(async (size) => ({ size, data: await resizePng(size) })),
  );
  await writeFile(resolve(root, "app/favicon.ico"), buildIco(icoFrames));

  await writeFile(resolve(root, "app/icon.png"), await resizePng(512));
  // iOS masks the home-screen icon itself, so keep this one square.
  await writeFile(
    resolve(root, "app/apple-icon.png"),
    await resizePng(180, { rounded: false }),
  );

  console.log("Generated app/favicon.ico, app/icon.png, app/apple-icon.png");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
